import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FileService } from 'src/app/core/services/file.service';
import { OrderByDatePipe } from 'src/app/core/order-by-date.pipe';

@Component({
  selector: 'app-student-files',
  standalone: true,
  imports: [CommonModule,OrderByDatePipe],
  templateUrl: './student-files.component.html',
  styleUrls: ['./student-files.component.scss']
})
export class StudentFilesComponent implements OnInit {
  classId!: number;
  files: any[] = [];
  loading = true;

  constructor(private route: ActivatedRoute, private fileService: FileService) {}

  ngOnInit() {
    this.classId = +this.route.snapshot.params['id'];
    this.fileService.getFilesByClass(this.classId).subscribe({
      next: res => { this.files = res; this.loading = false; },
      error: err => { console.error('Erreur:', err); this.loading = false; }
    });
  }

  getTypeLabel(type: any): string {
    if (typeof type === 'number') {
      switch (type) {
        case 0: return 'Cours';
        case 1: return 'TD';
        case 2: return 'TP';
        default: return 'Autre';
      }
    }
    return type;
  }
}
<section class="container py-5">
  <h2 class="fw-bold text-center mb-4">
    📚 Ressources de la classe
  </h2>

  <div *ngIf="loading" class="text-center my-5">
    <div class="spinner-border text-primary"></div>
  </div>

  <div *ngIf="!loading && files.length > 0; else noFiles">
  <div class="files-grid">
  <div class="file-card shadow-sm" *ngFor="let f of files | orderByDate">
    <!-- ✅ Type coloré -->
    <div class="file-type" [ngClass]="getTypeLabel(f.type).toLowerCase()">
      {{ getTypeLabel(f.type) }}
    </div>

    <!-- Titre -->
    <h5 class="file-title">{{ f.title }}</h5>

    <!-- Date d’ajout -->
    <p class="file-date text-muted small mb-2">
      <i class="bi bi-calendar-event me-1"></i>
      Ajouté le {{ f.createdAt | date:'dd MMM yyyy, HH:mm' }}
    </p>

    <!-- Boutons -->
    <div class="file-actions">
      <a [href]="f.fileUrl" target="_blank" class="btn btn-outline-primary btn-sm w-100 mb-2">
        <i class="bi bi-download me-1"></i> Télécharger
      </a>
      <button *ngIf="showDelete" class="btn btn-outline-danger btn-sm w-100" (click)="delete(f.id)">
        <i class="bi bi-trash me-1"></i> Supprimer
      </button>
    </div>
  </div>
</div>

  </div>

  <ng-template #noFiles>
    <div class="alert alert-info text-center mt-5">
      📭 Aucune ressource disponible pour cette classe.
    </div>
  </ng-template>
</section>
